        var redirectResponse = await redirectClient.GetAsync($"/{code}");

        Assert.Equal(HttpStatusCode.TemporaryRedirect, redirectResponse.StatusCode);
        Assert.Equal(targetUrl, redirectResponse.Headers.Location?.ToString());
